import { STANDALONE_BIN, WORKFLOWS_TOPIC } from '../command-ids.js';
export function followUpCommand({ bin, selection = {} }, ...words) {
    const prefix = bin === STANDALONE_BIN ? [bin] : [bin, WORKFLOWS_TOPIC];
    return [...prefix, ...words, ...selectionFlags(selection)].join(' ');
}
function selectionFlags({ deployment, partition, allPartitions }) {
    return [
        ...(deployment === undefined ? [] : ['--deployment', deployment]),
        ...(partition === undefined ? [] : ['--partition', partition]),
        ...(allPartitions === true ? ['--all-partitions'] : []),
    ];
}
